test('invoiceTotals with tier discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 }, // no explicit discount, uses 5% tier
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  // lineTotal = 17000, discount = 850, after discount = 16150
  // VAT = 16150 * 21 / 100 = 3391.5 rounds to 3392 (banker's rounding to nearest even)
  // total = 17000 - 850 + 3392 = 19542
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 850);
  assert.equal(totals.vat, 3392);
  assert.equal(totals.total, 19542);
});

test('invoiceTotals clamps total at 0', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, discountPercent: 100, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

