import { ok, fail } from './result.js';
import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Validate discountPercent is a number between 0 and 100.
 * @param {any} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate the due date based on terms and issue date.
 * @param {string} issueDate in YYYY-MM-DD format
 * @param {string} terms NET14, NET30, or EOM
 * @returns {string} due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  }
  if (terms === 'NET30') {
    return addDays(issueDate, 30);
  }
  if (terms === 'EOM') {
    // Get the last day of the month by going to first day of next month and back 1 day
    const [year, month, day] = issueDate.split('-').map(Number);
    const nextMonth = month === 12 ? `${year + 1}-01-01` : `${year}-${String(month + 1).padStart(2, '0')}-01`;
    return addDays(nextMonth, -1);
  }
  return null;
}

/**
 * Create an invoice from customer id, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} input
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and set terms (default to NET30)
  const finalTerms = terms ?? 'NET30';
  if (!['NET14', 'NET30', 'EOM'].includes(finalTerms)) return fail('TERMS_INVALID');

  // Validate lines is not empty
  if (!lines || !Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Get tier discount for this customer
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  // Enrich and validate lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    // Use explicit discountPercent if provided, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;

    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const dueDate = calculateDueDate(issueDate, finalTerms);

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,

  const dueDate = calculateDueDate(issueDate, finalTerms);

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    terms: finalTerms,
    dueDate,
    status: 'draft',
    lines: enrichedLines,
  };

  return ok(invoice);
}

